css:
& .am-head h1 { font-family: var(--head-font); font-weight: 800; font-size: 34px; letter-spacing: 0.01em; text-transform: uppercase; }
& .am-panel-head h2 { font-family: var(--head-font); font-weight: 800; font-size: 16px; letter-spacing: 0.03em; text-transform: uppercase; }
& .am-panel-id { font-family: var(--head-font); font-weight: 800; }
@media (max-width: 760px) {
  & .am-head h1 { font-size: 27px; }
}
& body { background-image: radial-gradient(var(--pop-dots) 1.3px, transparent 1.5px); background-size: 8px 8px; }
& .am-head h1 { color: var(--pop-title-fg); text-shadow: 3px 3px 0 var(--pop-title-shadow); }
& .am-panel-head { background: var(--head-bg); color: var(--head-fg); }
& .am-panel-id { background: var(--pop-yellow); color: var(--head-fg); }
& .am-panel-meta { color: var(--head-fg); }
& .am-panel-head .am-comment-btn { color: var(--head-fg); }
& .am-panel:hover .am-panel-head .am-comment-btn { border-color: color-mix(in srgb, var(--head-fg) 55%, transparent); }
& .am-panel-head .am-comment-btn:hover, & .am-panel-head .am-comment-btn:focus-visible, & .am-panel-head .am-comment-btn[aria-expanded="true"], & .am-panel-head .am-comment-btn.am-comment-btn--on { color: var(--head-fg); border-color: var(--head-fg); }
